impl PeerAddress {
	pub fn to_json(&self) -> String {
		let mut s = String::new();
		self.to_json_into(&mut s);
		s
	}
	pub fn to_text(&self) -> String {
		let mut s = String::new();
		self.to_text_into(&mut s);
		s
	}
	pub fn to_cbor(&self) -> Vec<u8> {
		let mut v = Vec::new();
		self.to_cbor_into(&mut v);
		v
	}
	pub fn to_json_into(&self, out: &mut String) {
		out.push('{');
		out.push_str("\"kind\":");
		self.kind.to_json_into(out);
		out.push(',');
		out.push_str("\"bytes\":");
		out.push('[');
		let mut v59 = true;
		for v58 in self.bytes.iter() {
			if !v59 {
				out.push(',');
			}
			v59 = false;
			let _ = write!(out, "{}", v58);
		}
		out.push(']');
		out.push('}');
	}
	pub fn to_text_into(&self, out: &mut String) {
		out.push('{');
		out.push_str("kind=");
		self.kind.to_text_into(out);
		out.push_str(", ");
		out.push_str("bytes=");
		out.push('[');
		let mut v61 = true;
		for v60 in self.bytes.iter() {
			if !v61 {
				out.push_str(", ");
			}
			v61 = false;
			let _ = write!(out, "{}", v60);
		}
		out.push(']');
		out.push('}');
	}
	pub fn to_cbor_into(&self, out: &mut Vec<u8>) {
		crate::codec::cbor::map(out, 2);
		crate::codec::cbor::text(out, "kind");
		self.kind.to_cbor_into(out);
		crate::codec::cbor::text(out, "bytes");
		crate::codec::cbor::array(out, self.bytes.len());
		for v62 in self.bytes.iter() {
			crate::codec::cbor::uint(out, *v62 as u64);
		}
	}
}

